/**
 * Regenerates src/data/surveys/aggregates/index.ts so every <slug>.json in
 * that directory is loaded by src/lib/surveys/frozen.ts.
 */
import { readdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

export const aggregatesDir = join(
  import.meta.dirname,
  '..',
  'src/data/surveys/aggregates'
)

export function renderAggregatesIndex(dir = aggregatesDir): string {
  const slugs = readdirSync(dir)
    .filter(f => f.endsWith('.json'))
    .map(f => f.slice(0, -5))
    .sort()
  return [
    '// Generated by scripts/aggregates-index.ts. Do not edit.',
    ...slugs.map((s, i) => `import a${i} from './${s}.json'`),
    '',
    'const aggregates: Record<string, unknown> = {',
    ...slugs.map((s, i) => `  '${s}': a${i},`),
    '}',
    'export default aggregates',
    '',
  ].join('\n')
}

export function writeAggregatesIndex(dir = aggregatesDir): void {
  writeFileSync(join(dir, 'index.ts'), renderAggregatesIndex(dir))
}
